export function applyTechniqueDetails(collections) {
  for (const collection of collections) {
    if (collection.scaffold) continue;
    for (const subject of collection.subjects) {
      for (const topic of subject.topics) {
        const key = `${collection.id}/${subject.id}/${topic.id}`;
        const details = techniqueDetails[key];
        if (!details || details.length !== topic.bullets.length) throw new Error(`Incomplete technique details: ${key}`);
        topic.bullets = topic.bullets.map((item, index) => {
          if (details[index].name !== item.name) throw new Error(`Technique order mismatch: ${key} / ${item.name}`);
          return { ...item, ...details[index] };
        });
      }
    }
  }
  return collections;
}
